"""Model of Chromium's GetAutogeneratedThemeColors (chrome/common/themes/autogenerated_theme_util.cc):
the frame and toolbar a BrowserThemeColor policy seed produces. Usage: python3 autogenerated-theme.py "#F2F0E5" ..."""
import colorsys, sys
DARK=(0x20,0x21,0x24); WHITE=(255,255,255)
def lin(c): c/=255; return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
def lum(c): r,g,b=c; return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b)
def cr(a,b): la,lb=sorted((lum(a),lum(b)),reverse=True); return (la+0.05)/(lb+0.05)
def maxc(c): return DARK if cr(c,DARK)>=cr(c,WHITE) else WHITE
def hsl(c): h,l,s=colorsys.rgb_to_hls(*[x/255 for x in c]); return [h,s,l]
def rgb(h): r,g,b=colorsys.hls_to_rgb(h[0],h[2],h[1]); return tuple(round(x*255) for x in (r,g,b))
def blend_min(fg,bg_text,target,ratio):
    # BlendForMinContrast: blend `fg` toward target until contrast with bg_text >= ratio
    if cr(fg,bg_text)>=ratio: return fg
    for a in range(0,256):
        t=a/255; c=tuple(round(fg[i]*(1-t)+target[i]*t) for i in range(3))
        if cr(c,bg_text)>=ratio: return c
    return target
def lighten(src,base,ratio,white_c):
    h=hsl(src); lo,hi=h[2],1.0
    while hi-lo>0.01:
        h[2]=lo+(hi-lo)/2; c=rgb(h)
        if cr(base,c)>=ratio or cr(WHITE,c)<white_c: hi=h[2]
        else: lo=h[2]
    h[2]=hi; return rgb(h)
def darken(c,d): h=hsl(c); h[2]-=d; return rgb(h) if h[2]>=0 else c
def auto(seed):
    f=seed
    while True:
        ft=maxc(f); f=blend_min(f,ft,maxc(ft),7.0)
        at=lighten(f,f,1.3,0.0)
        pref=4.0 if hsl(f)[2]<=0.05 else 1.6   # ForDark value assumed
        at=lighten(at,f,pref,1.3)
        if cr(f,at)<1.3: f=darken(f,0.03); continue
        if lum(at)>0.18:  # light
            at=lighten(at,maxc(at),7.0,0.0); break
        if cr(at,WHITE)>=7.0: break
        f=darken(f,0.03)
    return f,at
H=lambda c:"#%02X%02X%02X"%c
for s in sys.argv[1:]:
    c=tuple(int(s[i:i+2],16) for i in (1,3,5)); f,a=auto(c); print(s,"frame",H(f),"toolbar",H(a))
